//! The IGES corpus manifest of IO.CAD.IGES.SECT (`fixtures/io/cad/iges/sect/iges.toml`,
//! generated by `make_fixtures.py` there) parses with the real IO.CORP.MANIF parser.
//!
//! This test lives here rather than in `fid-io-iges`: `fid-io-corp` is a `tool`-layer crate,
//! and the layer gate forbids any other crate, dev-dependencies included, from depending on it.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_io_corp::{Expect, Manifest};
use std::path::PathBuf;

fn manifest_text() -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/io/cad/iges/sect/iges.toml");
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

#[test]
fn iges_manifest_parses_with_the_corpus_parser() {
    let text = manifest_text();
    let m = Manifest::parse(&text, "iges").unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(m.format.as_str(), "iges");
    assert_eq!(m.entries.len(), 12);
    let accepts = m.entries.iter().filter(|e| matches!(e.expect, Expect::Accept { .. })).count();
    assert_eq!(accepts, 6);
    assert!(m.entries.iter().all(|e| e.licence == "CC-BY-4.0"));
    // The format key must equal the file stem.
    assert!(Manifest::parse(&text, "cad.iges").is_err());
}
